export GOFLAGS=-mod=vendor GOPROXY=off GOSUMDB=off GOTOOLCHAIN=local GOWORK=off GOCACHE="${GOCACHE:-/tmp/morph/go-build}" GOPATH="${GOPATH:-/tmp/morph/go}"
P=$PWD/probe/project-registry; rm -rf $P; mkdir -p $P; trap 'rm -rf $P registry/project-registry_probe_test.go' EXIT
cat > $P/guard.mjs <<'MORPH_GUARD_EOF'
// Guard of a Go module: the layer rules and the Guardrail rules of the record, and the test-file rules. `morph plan
// --checks` inlines this file into every acceptance. Imports and calls are read by the go tool (a go/parser scan of
// each given code file), never by grep: a word in a comment is not an import. Node's standard library only. Every
// rule is checked per FILE, never per package: a red names the importing file and line, so a package-mate's import
// is never this card's red (P31b, issue #42).
// morph-guard-contract: 3
//   node guard.mjs src <file,file,...> <mods> <layers> <rules>  the packages of these Go files, all four arguments
//                                                         written by `morph plan --checks` from the record:
//     mods   = the module paths the card's Component declares (`uses`): a path or a path + "/...", ","-joined ('' none);
//              a file may import the standard library (narrowed only by the rules below) and these, nothing else
//              outside the module;
//     layers = JSON {"<package dir>": ["<dir it may import>", ...]} from the `uses: <Component>` steps (contract 2): a
//              file of a package dir it lacks may import no other package of the module;
//     rules  = JSON {"<package dir>": {"<rule id>": "<the Guardrail and where the record attaches it>"}} from the
//              record's canonical Guardrail names (contract 3).
//              A missing layers or rules argument is red, never "everything allowed" (issue #46): re-cut with morph plan.
//   node guard.mjs tests <file> <min> <max> [lits.json]   one Go test file; lits = strings it must hold; it may import
//                                                         the module's packages and go.mod's direct requirements
// Rule ids (each checked in the given code files, never in a _test.go file; a red names the file and line):
//   no-shell     no import of os/exec
//   no-clock     no time.Now, time.Since, time.Until; no import of math/rand, math/rand/v2, crypto/rand
//   no-network   no import of net, net/http, net/rpc, net/smtp or a package under net/http/, net/rpc/
//   no-env       no os.Getenv, os.LookupEnv, os.Environ, os.Setenv, os.Unsetenv, os.Clearenv, os.ExpandEnv
//   stdlib-only  no import outside the standard library and the module, the declared modules included
//   pure         all of the above but stdlib-only, and no import of os, time, syscall, unsafe
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const bad = [];
const PURE_FORBIDDEN = ["os", "os/exec", "net", "net/http", "time", "math/rand", "math/rand/v2", "syscall", "unsafe"];
const RULE_ORDER = ["no-shell", "no-clock", "no-network", "no-env", "stdlib-only", "pure"];
const CLOCK_IMPORTS = ["math/rand", "math/rand/v2", "crypto/rand"];
const NET_IMPORTS = ["net", "net/http", "net/rpc", "net/smtp"];
const CLOCK_USES = ["time.Now", "time.Since", "time.Until"];
const ENV_USES = ["os.Getenv", "os.LookupEnv", "os.Environ", "os.Setenv", "os.Unsetenv", "os.Clearenv", "os.ExpandEnv"];
const TEST_CALL = /^func Test(?:[A-Z0-9_]\w*)?\s*\(/gm;

function modulePath() {
  const text = fs.existsSync("go.mod") ? fs.readFileSync("go.mod", "utf8") : "";
  const m = /^module\s+(\S+)/m.exec(text);
  if (!m) bad.push("guard: go.mod has no module line");
  return m ? m[1] : "";
}
function isStd(imp) {
  return !imp.split("/")[0].includes(".");
}
function checkSrc(files, allowed, layers, rules) {
  const mod = modulePath();
  const code = [];
  for (const f of files) {
    const rel = f.split(path.sep).join("/");
    if (!rel.endsWith("_test.go")) code.push([f, rel]);
  }
  if (code.length === 0) return;
  const scanned = scanFiles(code.map(([f]) => f));
  for (const [f, rel] of code) {
    const r = scanned[f];
    if (!r) { bad.push(`guard: ${rel}: not scanned`); continue; }
    if (r.error) { bad.push(`guard: ${rel}: does not parse: ${r.error}`); continue; }
    const dir = path.posix.dirname(rel);
    const active = rules[dir] ?? {};
    const first = (ids) => RULE_ORDER.find((id) => ids.includes(id) && id in active);
    for (const h of r.imports) {
      const imp = h.name;
      const id = first(importRules(imp, mod));
      if (id) { bad.push(`guard: ${rel}:${h.line}: imports ${imp}: ${active[id]}`); continue; }
      if (imp === mod || imp.startsWith(mod + "/")) {
        const target = imp === mod ? "." : imp.slice(mod.length + 1);
        if (target === dir) continue;
        const may = layers[dir] ?? [];
        if (!may.includes(target))
          bad.push(`guard: ${rel}:${h.line}: imports ${imp}: the record has no 'uses' from ${dir} to ${target} (allowed: ${may.join(", ") || "none"})`);
        continue;
      }
      if (!isStd(imp) && !allowed.some((m) => imp === m || imp.startsWith(m + "/")))
        bad.push(`guard: ${rel}:${h.line}: imports ${imp}: not a dependency the record gives this Component (allowed: the standard library${allowed.length ? ", " + allowed.join(", ") : ""})`);
    }
    for (const h of r.uses) {
      const id = first(useRules(h.name));
      if (id) bad.push(`guard: ${rel}:${h.line}: uses ${h.name}: ${active[id]}`);
    }
  }
}
// The go/parser scan of the code files: per file its imports and every selector <imported package>.<Name>, with lines.
const SCAN = `package main

import (
	"encoding/json"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"regexp"
	"strconv"
	"strings"
)

type hit struct {
	Name string \`json:"name"\`
	Line int    \`json:"line"\`
}
type file struct {
	Error   string \`json:"error,omitempty"\`
	Imports []hit  \`json:"imports"\`
	Uses    []hit  \`json:"uses"\`
}

var version = regexp.MustCompile("^v[0-9]+$")

func main() {
	out := map[string]file{}
	fset := token.NewFileSet()
	for _, p := range os.Args[1:] {
		r := file{Imports: []hit{}, Uses: []hit{}}
		f, err := parser.ParseFile(fset, p, nil, parser.SkipObjectResolution)
		if err != nil {
			r.Error = err.Error()
			out[p] = r
			continue
		}
		names := map[string]string{}
		for _, s := range f.Imports {
			ip, _ := strconv.Unquote(s.Path.Value)
			r.Imports = append(r.Imports, hit{ip, fset.Position(s.Pos()).Line})
			parts := strings.Split(ip, "/")
			name := parts[len(parts)-1]
			if version.MatchString(name) && len(parts) > 1 {
				name = parts[len(parts)-2]
			}
			if s.Name != nil {
				name = s.Name.Name
			}
			names[name] = ip
		}
		ast.Inspect(f, func(n ast.Node) bool {
			if sel, ok := n.(*ast.SelectorExpr); ok {
				if id, ok := sel.X.(*ast.Ident); ok {
					if ip, ok := names[id.Name]; ok {
						r.Uses = append(r.Uses, hit{ip + "." + sel.Sel.Name, fset.Position(sel.Pos()).Line})
					}
				}
			}
			return true
		})
		out[p] = r
	}
	_ = json.NewEncoder(os.Stdout).Encode(out)
}
`;
function scanFiles(files) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "morph-guard-"));
  try {
    fs.writeFileSync(path.join(dir, "go.mod"), "module morphguardscan\n\ngo 1.21\n");
    fs.writeFileSync(path.join(dir, "main.go"), SCAN);
    const out = execFileSync("go", ["run", ".", ...files.map((f) => path.resolve(f))], {
      cwd: dir, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"],
      env: { ...process.env, GOFLAGS: "-mod=mod", GOWORK: "off" },
    });
    const doc = JSON.parse(out);
    const byFile = {};
    for (const f of files) byFile[f] = doc[path.resolve(f)];
    return byFile;
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}
function importRules(imp, mod) {
  const out = [];
  if (imp === "os/exec") out.push("no-shell");
  if (CLOCK_IMPORTS.includes(imp)) out.push("no-clock");
  const net = NET_IMPORTS.includes(imp) || imp.startsWith("net/http/") || imp.startsWith("net/rpc/");
  if (net) out.push("no-network");
  if (!isStd(imp) && imp !== mod && !imp.startsWith(mod + "/")) out.push("stdlib-only");
  if (imp === "os/exec" || CLOCK_IMPORTS.includes(imp) || net || PURE_FORBIDDEN.includes(imp)) out.push("pure");
  return out;
}
function useRules(sym) {
  const out = [];
  if (CLOCK_USES.includes(sym)) out.push("no-clock", "pure");
  if (ENV_USES.includes(sym)) out.push("no-env", "pure");
  return out;
}
function fileImports(text) {
  const out = [];
  for (const m of text.matchAll(/^import\s+(?:[\w.]+\s+)?"([^"]+)"/gm)) out.push(m[1]);
  for (const m of text.matchAll(/^import\s*\(([\s\S]*?)^\)/gm))
    for (const line of m[1].split("\n")) {
      const s = /^\s*(?:[\w.]+\s+)?"([^"]+)"/.exec(line.replace(/\/\/.*$/, ""));
      if (s) out.push(s[1]);
    }
  return out;
}
// go.mod's direct requirements: the module paths of its `require` lines and blocks, without the
// lines marked `// indirect`. A test file may import them (a judge needs a declared module's test doubles, e.g. an
// in-memory transport); the scaffold vendored them, so the test builds offline.
function directRequires() {
  const text = fs.existsSync("go.mod") ? fs.readFileSync("go.mod", "utf8") : "";
  const out = [];
  const take = (line) => {
    if (/\/\/\s*indirect\b/.test(line)) return;
    const m = /^\s*([^\s/][^\s]*)\s+v\S+/.exec(line.replace(/\/\/.*$/, ""));
    if (m && !out.includes(m[1])) out.push(m[1]);
  };
  for (const m of text.matchAll(/^require\s*\(([\s\S]*?)^\)/gm)) for (const line of m[1].split("\n")) take(line);
  for (const m of text.matchAll(/^require\s+([^(\s].*)$/gm)) take(m[1]);
  return out;
}
function checkTest(file, min, max, lits) {
  if (!fs.existsSync(file)) { bad.push(`guard: ${file} missing`); return; }
  const text = fs.readFileSync(file, "utf8");
  const mod = modulePath();
  const requires = directRequires();
  for (const imp of fileImports(text))
    if (!isStd(imp) && !(imp === mod + "/internal/testhelp" || imp.startsWith(mod + "/")) &&
        !requires.some((r) => imp === r || imp.startsWith(r + "/")))
      bad.push(`guard: ${file} imports ${imp} (the standard library${requires.length ? ", " + mod + "/internal/testhelp, " + requires.join(", ") : " and " + mod + "/internal/testhelp"} only)`);
  const code = text.split("\n").map((l) => l.replace(/\/\/.*$/, "")).join("\n");
  for (const m of code.matchAll(/\.(Skip|Skipf|SkipNow)\(|\btesting\.Short\(/g))
    bad.push(`guard: ${file} calls ${m[1] ?? "testing.Short"} (a test runs or fails, it is never skipped)`);
  const count = (text.match(TEST_CALL) ?? []).length;
  if (count < min || count > max) bad.push(`guard: ${file} has ${count} func Test, expected ${min}..${max}`);
  for (const lit of lits) if (!text.includes(lit)) bad.push(`guard: ${file} does not mention the example literal ${JSON.stringify(lit)}`);
}

const [mode, a, b, c, d] = process.argv.slice(2);
if (mode === "src" && c === undefined) bad.push("guard: no layer edges given — re-cut with morph plan");
else if (mode === "src" && d === undefined) bad.push("guard: no Guardrail rules given — re-cut with morph plan");
else if (mode === "src") checkSrc((a ?? "").split(",").filter(Boolean), (b ?? "").split(",").filter(Boolean), JSON.parse(c), JSON.parse(d));
else if (mode === "tests") checkTest(a, Number(b), Number(c), d ? JSON.parse(fs.readFileSync(d, "utf8")) : []);
else bad.push(`guard: unknown mode ${mode}`);
for (const x of bad) console.log(x);
process.exit(bad.length ? 1 : 0);
MORPH_GUARD_EOF
cat > $P/firstdiff.mjs <<'MORPH_FIRSTDIFF_EOF'
// First-difference locator of a Go module: reads a `go test` log and, for every failed comparison printed by the
// module's internal/testhelp Equal ("got:  <x>" on one line, "want: <y>" on the next, indented under the failing test's
// line), prints where the two first differ, with 40 chars of context on each side. `morph plan --checks` inlines this
// file into every acceptance.
//   node firstdiff.mjs <go test log>
import fs from "node:fs";

const lines = fs.readFileSync(process.argv[2], "utf8").split("\n");
const pairs = [];
for (let i = 0; i + 1 < lines.length; i++) {
  const got = /^\s+got:\s+(.*)$/.exec(lines[i]);
  const want = /^\s+want:\s+(.*)$/.exec(lines[i + 1]);
  if (got && want) {
    pairs.push([want[1], got[1]]);
    i++;
  }
}
let shown = 0;
for (const [e, r] of pairs) {
  if (e === r || shown >= 6) continue;
  let k = 0;
  while (k < e.length && k < r.length && e[k] === r[k]) k++;
  const at = (s) => JSON.stringify((k > 40 ? "..." : "") + s.slice(Math.max(0, k - 40), k + 40));
  console.log(`first difference at char ${k} of ${e.length}/${r.length}: expected ${at(e)} received ${at(r)}`);
  shown++;
}
MORPH_FIRSTDIFF_EOF
cat > $P/overlay.json <<'MORPH_CONF_EOF'
{"Replace":{}}
MORPH_CONF_EOF
cat > $P/full.json <<'MORPH_CONF_EOF'
{"Replace":{}}
MORPH_CONF_EOF
echo '== build'; go build -overlay $P/overlay.json ./registry
echo '== vet'; E=0; go vet -overlay $P/overlay.json ./registry || E=1
echo '== gofmt'; F=$(gofmt -l registry/registry.go 2>&1) || true; [ -z "$F" ] || { echo "gofmt -l lists: $F"; gofmt -d registry/registry.go 2>&1 | head -60; E=1; }
echo '== guard'; node $P/guard.mjs src registry/registry.go '' '{"registry":[]}' '{"registry":{}}'
echo '== probe'; cat > registry/project-registry_probe_test.go <<'MORPH_PROBE_EOF'
package registry

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
	"time"

	"morphstudio/internal/testhelp"
	"morphstudio/queue"
)

var pPRZeta = Project{Name: "zeta", Language: "go", RepoURL: "https://github.com/o/zeta", Dir: "/p/zeta", User: "mu-zeta", Caps: queue.Caps{ClaudeUSD: 30, Hours: 3, ExecutorUSD: 5}, CreatedAt: time.Date(2026, 10, 8, 15, 0, 0, 0, time.UTC)}
var pPRAlpha = Project{Name: "alpha", Language: "python", RepoURL: "https://github.com/o/alpha", Dir: "/p/alpha", User: "mu-alpha", Caps: queue.Caps{ClaudeUSD: 12, Hours: 2, ExecutorUSD: 4}, CreatedAt: time.Date(2026, 10, 8, 15, 1, 0, 0, time.UTC)}

func pPROpen(t *testing.T, what, base string) *Registry {
	t.Helper()
	r, err := Open(base)
	if err != nil {
		t.Fatalf("%s: Open(%s) error %v, want nil", what, base, err)
	}
	if r == nil {
		t.Fatalf("%s: Open(%s) returned a nil *Registry", what, base)
	}
	return r
}

func pPRNames(ps []Project) []string {
	out := []string{}
	for _, p := range ps {
		out = append(out, p.Name)
	}
	return out
}

func pPRDir(t *testing.T, dir string) []string {
	t.Helper()
	es, err := os.ReadDir(dir)
	if err != nil {
		t.Errorf("read dir %s: %v", dir, err)
		return nil
	}
	out := []string{}
	for _, e := range es {
		out = append(out, e.Name())
	}
	sort.Strings(out)
	return out
}

func pPRMode(t *testing.T, path string) os.FileMode {
	t.Helper()
	st, err := os.Stat(path)
	if err != nil {
		t.Errorf("stat %s: %v", path, err)
		return 0
	}
	return st.Mode() & 0o777
}

// pPRTwo is the registry after example 2: zeta then alpha added.
func pPRTwo(t *testing.T, what string) (*Registry, string) {
	t.Helper()
	base := filepath.Join(t.TempDir(), "state")
	r := pPROpen(t, what, base)
	if err := r.Add(pPRZeta); err != nil {
		t.Fatalf("%s: Add(zeta) error %v, want nil", what, err)
	}
	if err := r.Add(pPRAlpha); err != nil {
		t.Fatalf("%s: Add(alpha) error %v, want nil", what, err)
	}
	return r, base
}

func TestProbeProjectRegistryExample1(t *testing.T) {
	base := filepath.Join(t.TempDir(), "state")
	r := pPROpen(t, "example 1", base)
	st, err := os.Stat(base)
	testhelp.Equal(t, "example 1 base directory exists", err == nil && st.IsDir(), true)
	testhelp.Equal(t, "example 1 base directory mode", pPRMode(t, base), os.FileMode(0o700))
	l := r.List()
	testhelp.Equal(t, "example 1 List is non-nil", l != nil, true)
	testhelp.Equal(t, "example 1 List", l, []Project{})
	p, err := r.Get("demo")
	testhelp.Equal(t, "example 1 Get(demo) project", p, Project{})
	testhelp.Equal(t, "example 1 Get(demo) is ErrNotFound", errors.Is(err, ErrNotFound), true)
	testhelp.Equal(t, "example 1 Base", r.Base(), base)
	// variant: another base name, nested two levels deep
	base2 := filepath.Join(t.TempDir(), "x", "reg-7")
	r2 := pPROpen(t, "example 1 variant", base2)
	testhelp.Equal(t, "example 1 variant Base", r2.Base(), base2)
	testhelp.Equal(t, "example 1 sentinel texts", []string{ErrNotFound.Error(), ErrExists.Error(), ErrBadName.Error(), ErrNoState.Error()}, []string{"project not found", "project exists", "bad project name", "no state"})
}

func TestProbeProjectRegistryExample2(t *testing.T) {
	r, base := pPRTwo(t, "example 2")
	l := r.List()
	testhelp.Equal(t, "example 2 List names", pPRNames(l), []string{"alpha", "zeta"})
	testhelp.Equal(t, "example 2 List", l, []Project{pPRAlpha, pPRZeta})
	b, err := os.ReadFile(filepath.Join(base, "projects.json"))
	if err != nil {
		t.Fatalf("example 2: read projects.json: %v", err)
	}
	var file []Project
	testhelp.Equal(t, "example 2 projects.json decodes", json.Unmarshal(b, &file), error(nil))
	testhelp.Equal(t, "example 2 projects.json equals List", file, l)
	want, _ := json.MarshalIndent(l, "", "  ")
	testhelp.Equal(t, "example 2 projects.json is MarshalIndent with two spaces", strings.TrimRight(string(b), "\n"), string(want))
	testhelp.Equal(t, "example 2 base holds only projects.json", pPRDir(t, base), []string{"projects.json"})
	// variant: a third project sorts between them; the file follows
	m := Project{Name: "m-1", Language: "typescript", Dir: "/srv/m-1", User: "mu-m1", Caps: queue.Caps{ClaudeUSD: 7.5, Hours: 1, ExecutorUSD: 2}, CreatedAt: time.Date(2027, 1, 2, 3, 4, 5, 0, time.UTC)}
	testhelp.Equal(t, "example 2 variant Add(m-1)", r.Add(m), error(nil))
	testhelp.Equal(t, "example 2 variant List", r.List(), []Project{pPRAlpha, m, pPRZeta})
	b, _ = os.ReadFile(filepath.Join(base, "projects.json"))
	file = nil
	_ = json.Unmarshal(b, &file)
	testhelp.Equal(t, "example 2 variant projects.json", file, []Project{pPRAlpha, m, pPRZeta})
	testhelp.Equal(t, "example 2 variant base holds only projects.json", pPRDir(t, base), []string{"projects.json"})
}

func TestProbeProjectRegistryExample3(t *testing.T) {
	r, _ := pPRTwo(t, "example 3")
	testhelp.Equal(t, "example 3 Add(alpha) is ErrExists", errors.Is(r.Add(Project{Name: "alpha"}), ErrExists), true)
	for _, n := range []string{"Alpha", "-x", strings.Repeat("a", 41)} {
		testhelp.Equal(t, "example 3 Add("+n+") is ErrBadName", errors.Is(r.Add(Project{Name: n}), ErrBadName), true)
	}
	testhelp.Equal(t, "example 3 List still 2", pPRNames(r.List()), []string{"alpha", "zeta"})
	// variant: the name rule's edges on a fresh registry
	r2 := pPROpen(t, "example 3 variant", filepath.Join(t.TempDir(), "state"))
	for _, n := range []string{"", "a_b", "a.b", "-", "ab ", "zéta"} {
		testhelp.Equal(t, "example 3 variant Add("+n+") is ErrBadName", errors.Is(r2.Add(Project{Name: n}), ErrBadName), true)
	}
	for _, n := range []string{strings.Repeat("b", 40), "9-ok", "x"} {
		testhelp.Equal(t, "example 3 variant Add("+n+")", r2.Add(Project{Name: n}), error(nil))
	}
	testhelp.Equal(t, "example 3 variant List", pPRNames(r2.List()), []string{"9-ok", strings.Repeat("b", 40), "x"})
}

func TestProbeProjectRegistryExample4(t *testing.T) {
	r, base := pPRTwo(t, "example 4")
	r2 := pPROpen(t, "example 4 reopen", base)
	testhelp.Equal(t, "example 4 reopened List", r2.List(), r.List())
	g, err := r2.Get("zeta")
	testhelp.Equal(t, "example 4 Get(zeta)", g, pPRZeta)
	testhelp.Equal(t, "example 4 Get(zeta) error", err, error(nil))
	// variant: an Add after the reopen keeps the old entries in the file
	testhelp.Equal(t, "example 4 variant Add(beta)", r2.Add(Project{Name: "beta", Language: "go", User: "mu-beta"}), error(nil))
	r3 := pPROpen(t, "example 4 second reopen", base)
	testhelp.Equal(t, "example 4 variant names after reopen", pPRNames(r3.List()), []string{"alpha", "beta", "zeta"})
}

type pPRState struct {
	N int `json:"n"`
}

func TestProbeProjectRegistryExample5(t *testing.T) {
	r, base := pPRTwo(t, "example 5")
	testhelp.Equal(t, "example 5 SaveState(alpha)", r.SaveState("alpha", pPRState{7}), error(nil))
	var out pPRState
	testhelp.Equal(t, "example 5 LoadState(alpha) error", r.LoadState("alpha", &out), error(nil))
	testhelp.Equal(t, "example 5 LoadState(alpha) value", out, pPRState{7})
	var out2 pPRState
	testhelp.Equal(t, "example 5 LoadState(zeta) is ErrNoState", errors.Is(r.LoadState("zeta", &out2), ErrNoState), true)
	testhelp.Equal(t, "example 5 SaveState(nope) is ErrNotFound", errors.Is(r.SaveState("nope", pPRState{1}), ErrNotFound), true)
	var out3 pPRState
	testhelp.Equal(t, "example 5 LoadState(nope) is ErrNotFound", errors.Is(r.LoadState("nope", &out3), ErrNotFound), true)
	testhelp.Equal(t, "example 5 state.json mode", pPRMode(t, filepath.Join(base, "alpha", "state.json")), os.FileMode(0o600))
	testhelp.Equal(t, "example 5 project dir mode", pPRMode(t, filepath.Join(base, "alpha")), os.FileMode(0o700))
	// variant: a second save replaces the first; no temporary file is left
	testhelp.Equal(t, "example 5 variant SaveState(alpha, 42)", r.SaveState("alpha", pPRState{42}), error(nil))
	out = pPRState{}
	_ = r.LoadState("alpha", &out)
