  const got = /^\s+got:\s+(.*)$/.exec(lines[i]);
  const want = /^\s+want:\s+(.*)$/.exec(lines[i + 1]);
  if (got && want) {
    pairs.push([want[1], got[1]]);
    i++;
  }
